1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request whose required owner fields are missing or blank. Runs
13	 * first in the {@code POST /api/owners} pipeline so an incomplete body is a 400
14	 * before any owner is built or saved. It binds the body once and republishes it as
15	 * a variable for the later {@link BuildOwner} step.
16	 */
17	public class ValidateOwnerFields {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
20	            throws MissingOwnerFieldsException {
21	        List<String> missing = new ArrayList<>();
22	        require(missing, "firstName", request.getFirstName());
23	        require(missing, "lastName", request.getLastName());
24	        require(missing, "address", request.getAddress());
25	        require(missing, "city", request.getCity());
26	        require(missing, "telephone", request.getTelephone());
27	        if (!missing.isEmpty()) {
28	            throw new MissingOwnerFieldsException(missing);
29	        }
30	        validated.set(request);
31	    }
32	
33	    private static void require(List<String> missing, String field, String value) {
34	        if (value == null || value.isBlank()) {
35	            missing.add(field);
36	        }
37	    }
38	}
