5	/**
6	 * Thrown when a create-owner request is missing or blank in one or more required
7	 * fields. Handled by {@link MissingOwnerFieldsExceptionHandler}, which responds 400
8	 * with an {@code errors} array naming each offending field.
9	 */
10	public class MissingOwnerFieldsException extends Exception {
11	
12	    private final List<String> fields;
13	
14	    public MissingOwnerFieldsException(List<String> fields) {
15	        super("Missing or blank owner fields: " + String.join(", ", fields));
16	        this.fields = List.copyOf(fields);
17	    }
18	
19	    public List<String> getFields() {
20	        return this.fields;
